package com.beyondsignal.game.event; import static org.junit.jupiter.api.Assertions.*; import java.util.*; import org.junit.jupiter.api.Test; class ExplorationEventResolverTest{ @Test void resolvesValidChoiceDeterministically(){ var e=ExplorationEvent.pending("e",ExplorationEventType.DISTRESS_CALL,"Distress","Civilian vessel requires assistance.","s",10,List.of(ExplorationChoice.ASSIST,ExplorationChoice.IGNORE)); var r=new ExplorationEventResolver(); assertEquals(r.resolve(e,ExplorationChoice.ASSIST,77),r.resolve(e,ExplorationChoice.ASSIST,77)); } @Test void rejectsInvalidChoice(){ var e=ExplorationEvent.pending("e2",ExplorationEventType.DERELICT_VESSEL,"Derelict","Abandoned vessel.","s",1,List.of(ExplorationChoice.SALVAGE)); assertThrows(IllegalArgumentException.class,()->new ExplorationEventResolver().resolve(e,ExplorationChoice.HAIL,1)); }}
